// Normalize Remote OK jobs
const raw = $input.first().json;
const jobs = Array.isArray(raw) ? raw.slice(1) : []; // first item is metadata

return jobs.map(j => ({
  json: {
    job_id: `remoteok-${j.id || j.slug}`,
    job_title: j.position || '',
    company: j.company || '',
    job_url: j.url || `https://remoteok.com/remote-jobs/${j.id}`,
    source: 'Remote OK',
    location_text: j.location || 'Remote',
    salary: j.salary || '',
    description: j.description || '',
    posted_date: j.date || new Date().toISOString(),
    tags: Array.isArray(j.tags) ? j.tags.join(', ') : ''
  }
}));

// Normalize Remotive jobs
const raw = $input.first().json;
const jobs = raw.jobs || [];

return jobs.map(j => ({
  json: {
    job_id: `remotive-${j.id}`,
    job_title: j.title || '',
    company: j.company_name || '',
    job_url: j.url || '',
    source: 'Remotive',
    location_text: j.candidate_required_location || 'Remote',
    salary: j.salary || '',
    description: j.description || '',
    posted_date: j.publication_date || new Date().toISOString(),
    tags: Array.isArray(j.tags) ? j.tags.join(', ') : ''
  }
}));

// Normalize We Work Remotely RSS (XML parsed to string, needs manual parsing)
const body = $input.first().json.data || $input.first().json.body || '';
const items = [];

// Extract <item> blocks
const itemRegex = /<item>([\s\S]*?)<\/item>/g;
let match;
while ((match = itemRegex.exec(body)) !== null) {
  const block = match[1];
  const get = (tag) => {
    const m = block.match(new RegExp(`<${tag}[^>]*><!\\[CDATA\\[([\\s\\S]*?)\\]\\]><\/${tag}>|<${tag}[^>]*>([\\s\\S]*?)<\/${tag}>`));
    return m ? (m[1] || m[2] || '').trim() : '';
  };
  const url = get('link');
  items.push({
    json: {
      job_id: `wwr-${Buffer.from(url).toString('base64').slice(0, 16)}`,
      job_title: get('title'),
      company: get('title').split(':')[0] || '',
      job_url: url,
      source: 'We Work Remotely',
      location_text: 'Remote',
      salary: '',
      description: get('description'),
      posted_date: get('pubDate') || new Date().toISOString(),
      tags: get('category')
    }
  });
}

return items.length > 0 ? items : [{ json: { _empty: true } }];

// Normalize Himalayas jobs
const raw = $input.first().json;
const jobs = raw.jobs || raw.data || (Array.isArray(raw) ? raw : []);

return jobs.map(j => ({
  json: {
    job_id: `himalayas-${j.id || j.slug}`,
    job_title: j.title || j.position || '',
    company: (j.company && j.company.name) || j.companyName || '',
    job_url: j.applicationLink || j.url || `https://himalayas.app/jobs/${j.slug}`,
    source: 'Himalayas',
    location_text: j.locationRestrictions || j.location || 'Remote',
    salary: j.salary || (j.minSalary ? `${j.minSalary}-${j.maxSalary}` : ''),
    description: j.description || '',
    posted_date: j.publishedAt || j.createdAt || new Date().toISOString(),
    tags: Array.isArray(j.tags) ? j.tags.join(', ') : (j.categories || '')
  }
}));

// Normalize Dynamite Jobs RSS
const body = $input.first().json.data || $input.first().json.body || '';
const items = [];
const itemRegex = /<item>([\s\S]*?)<\/item>/g;
let match;
while ((match = itemRegex.exec(body)) !== null) {
  const block = match[1];
  const get = (tag) => {
    const m = block.match(new RegExp(`<${tag}[^>]*><!\\[CDATA\\[([\\s\\S]*?)\\]\\]><\/${tag}>|<${tag}[^>]*>([\\s\\S]*?)<\/${tag}>`));
    return m ? (m[1] || m[2] || '').trim() : '';
  };
  const url = get('link');
  items.push({
    json: {
      job_id: `dynamite-${Buffer.from(url).toString('base64').slice(0, 16)}`,
      job_title: get('title'),
      company: get('author') || '',
      job_url: url,
      source: 'Dynamite Jobs',
      location_text: 'Remote',
      salary: '',
      description: get('description'),
      posted_date: get('pubDate') || new Date().toISOString(),
      tags: get('category')
    }
  });
}

return items.length > 0 ? items : [{ json: { _empty: true } }];

// Normalize YC Work at a Startup
const raw = $input.first().json;
const jobs = raw.jobs || raw.results || (Array.isArray(raw) ? raw : []);

return jobs.map(j => ({
  json: {
    job_id: `yc-${j.id}`,
    job_title: j.title || j.role || '',
    company: (j.company && j.company.name) || j.companyName || '',
    job_url: j.url || `https://www.workatastartup.com/jobs/${j.id}`,
    source: 'YC Work at a Startup',
    location_text: j.remote_ok ? 'Remote' : (j.location || ''),
    salary: j.salary || '',
    description: j.description || j.body || '',
    posted_date: j.created_at || new Date().toISOString(),
    tags: Array.isArray(j.tags) ? j.tags.join(', ') : ''
  }
}));

// Remove empty placeholder items and ensure all fields exist
const jobs = $input.all();
const result = [];
for (const item of jobs) {
  if (item.json._empty) continue;
  if (!item.json.job_url || item.json.job_url === '') continue;
  result.push({
    json: {
      job_id: item.json.job_id || '',
      job_title: (item.json.job_title || '').trim(),
      company: (item.json.company || '').trim(),
      job_url: (item.json.job_url || '').trim(),
      source: item.json.source || '',
      location_text: (item.json.location_text || 'Remote').trim(),
      salary: (item.json.salary || '').trim(),
      description: (item.json.description || '').replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ').trim(),
      posted_date: item.json.posted_date || new Date().toISOString(),
      tags: (item.json.tags || '').trim(),
      date_found: new Date().toISOString().split('T')[0]
    }
  });
}
return result;

// Deduplicate: remove jobs whose URL or company+title already exists
const incoming = $('Clean & Normalize All').all();
const existing = $('Read Existing Job URLs').all();

const existingUrls = new Set(existing.map(e => (e.json.job_url || '').trim().toLowerCase()));
const existingKeys = new Set(existing.map(e => `${(e.json.company || '').toLowerCase()}::${(e.json.job_title || '').toLowerCase()}`));

const seen = new Set();
const result = [];

for (const item of incoming) {
  const url = (item.json.job_url || '').trim().toLowerCase();
  const key = `${(item.json.company || '').toLowerCase()}::${(item.json.job_title || '').toLowerCase()}`;
  if (existingUrls.has(url)) continue;
  if (existingKeys.has(key)) continue;
  if (seen.has(url)) continue;
  seen.add(url);
  result.push(item);
}

return result;

// Taiwan eligibility HARD filter — reject known blockers, keep global signals
const REJECT_PATTERNS = [
  /\bus\s*only\b/i, /\busa\s*only\b/i, /\bunited\s*states\s*only\b/i,
  /\bcanada\s*only\b/i, /\buk\s*only\b/i, /\bunited\s*kingdom\s*only\b/i,
  /\beu\s*only\b/i, /\beurope\s*only\b/i, /\baustralia\s*only\b/i,
  /must\s*be\s*based\s*in/i, /must\s*live\s*in/i, /must\s*reside\s*in/i,
  /must\s*be\s*authorized\s*to\s*work/i, /must\s*have\s*(us|uk|eu|canadian)\s*(work\s*)?auth/i,
  /local\s*work\s*permit\s*required/i, /\bwork\s*permit\s*required\b/i,
  /\bhybrid\b/i, /\bonsite\b/i, /\bon-site\b/i, /\boffice\s*required\b/i,
  /remote\s*within\s*(the\s*)?(us|usa|uk|canada|europe|eu|australia)/i,
  /\bfixed\s*us\s*hours\b/i, /\bfixed\s*eu\s*hours\b/i,
  /\bEST\s*(?:9|10|8)(?:am|:00)/i, /\bPST\s*(?:9|10|8)(?:am|:00)/i,
  /applicants\s*must\s*be\s*located\s*in/i,
  /\bvisa\s*sponsorship\s*required\b/i
];

const KEEP_SIGNALS = [
  /worldwide\s*remote/i, /work\s*from\s*anywhere/i, /\bglobal\s*remote\b/i,
  /\banywhere\b/i, /\bapac\s*remote\b/i, /\bapac\b/i,
  /international\s*contractors?\s*(?:accepted|welcome|ok)/i,
  /\bcontractor\s*role\b/i, /\bb2b\s*contractor\b/i,
  /hires?\s*via\s*deel/i, /hires?\s*via\s*remote\.com/i,
  /hires?\s*via\s*oyster/i, /\beer\s*supported\b/i,
  /employer\s*of\s*record/i, /\bremote\s*first\b/i,
  /\bdistributed\s*team\b/i, /\bfully\s*distributed\b/i,
  /\bdeel\b/i, /\boyster\s*hr\b/i, /\bremote\.com\b/i
];

const items = $input.all();
const passed = [];
const rejected = [];

for (const item of items) {
  const text = `${item.json.job_title} ${item.json.location_text} ${item.json.description} ${item.json.tags}`.toLowerCase();

  let hardReject = false;
  let rejectReason = '';
  for (const p of REJECT_PATTERNS) {
    if (p.test(text)) {
      hardReject = true;
      rejectReason = p.toString().replace(/\/.*/g, '').slice(1);
      break;
    }
  }

  let hasKeepSignal = KEEP_SIGNALS.some(p => p.test(text));

  if (hardReject && !hasKeepSignal) {
    item.json._hard_rejected = true;
    item.json._reject_reason = `Hard filter: ${rejectReason}`;
    rejected.push(item);
  } else {
    item.json._has_keep_signal = hasKeepSignal;
    passed.push(item);
  }
}

// Output on output 0: passed; output 1: rejected
return [passed, rejected];

// Write rejected hard-filter jobs to Rejected sheet data
const items = $input.all();
return items.map(item => ({
  json: {
    date_rejected: new Date().toISOString().split('T')[0],
    job_title: item.json.job_title,
    company: item.json.company,
    job_url: item.json.job_url,
    reason: item.json._reject_reason || 'Hard filter: country restriction or onsite'
  }
}));

// Prepare AI eligibility check prompt for each job
const item = $input.first();
const desc = item.json.description || '';
const truncated = desc.length > 3000 ? desc.slice(0, 3000) + '...' : desc;

item.json._ai_prompt = `You are filtering remote jobs for Jerry, who lives in Taiwan.

The most important rule: Jerry must be able to work this job while physically based in Taiwan.

Do not pass the job only because it says "remote."

Reject the job if it requires the worker to live in the US, Canada, UK, EU, Europe, Australia, or any specific country outside Taiwan.
Reject the job if it requires local work authorization outside Taiwan.
Reject the job if it is hybrid, onsite, or remote within one country only.
Reject the job if it requires fixed working hours that would force Jerry to work through the night in Taiwan (e.g. fixed EST/PST/CET hours).

Keep the job only if one of these is true:
- The job says worldwide remote
- The job says work from anywhere
- The job says global remote
- The job says APAC remote
- The job allows international contractors
- The job accepts people based anywhere
- The company hires through EOR, Deel, Remote.com, Oyster, or contractor agreement

Return JSON only — no extra text:
{
  "taiwan_eligible": "yes/no/unclear",
  "reason": "short reason",
  "location_risk": "low/medium/high",
  "timezone_risk": "low/medium/high",
  "contractor_possible": "yes/no/unclear",
  "decision": "keep/reject/manual_check"
}

Job title: ${item.json.job_title}
Company: ${item.json.company}
Location text: ${item.json.location_text}
Tags: ${item.json.tags}

Job post:
${truncated}`;

return [item];

// Parse AI response and merge back with job data
const aiResponse = $input.first().json;
const jobData = $('Prepare AI Prompt').first().json;

let aiResult = {};
try {
  const text = aiResponse.content[0].text;
  const jsonMatch = text.match(/\{[\s\S]*\}/);
  if (jsonMatch) {
    aiResult = JSON.parse(jsonMatch[0]);
  }
} catch (e) {
  aiResult = {
    taiwan_eligible: 'unclear',
    reason: 'AI parse error',
    location_risk: 'medium',
    timezone_risk: 'medium',
    contractor_possible: 'unclear',
    decision: 'manual_check'
  };
}

return [{
  json: {
    ...jobData,
    taiwan_eligible: aiResult.taiwan_eligible || 'unclear',
    taiwan_reason: aiResult.reason || '',
    location_risk: aiResult.location_risk || 'medium',
    timezone_risk: aiResult.timezone_risk || 'medium',
    contractor_possible: aiResult.contractor_possible || 'unclear',
    ai_decision: aiResult.decision || 'manual_check'
  }
}];

// Async filter: score async signals in description
const item = $input.first();
const text = `${item.json.description} ${item.json.tags} ${item.json.job_title}`.toLowerCase();

const ASYNC_HIGH = [
  /\basync\b/i, /\basynchronous\b/i, /\bno\s*meetings?\b/i,
  /\bflexible\s*hours\b/i, /\bflexible\s*schedule\b/i,
  /\bwork\s*across\s*time\s*zones?\b/i, /\blow\s*meeting\s*culture\b/i
];

const ASYNC_MED = [
  /\bdistributed\s*team\b/i, /\bfully\s*distributed\b/i,
  /\bremote\s*first\b/i, /\bremote-first\b/i,
  /\bself.directed\b/i, /\bautonomous\b/i
];

const SYNC_REJECT = [
  /strict\s*9\s*to\s*5/i, /fixed\s*(?:us|eu|est|pst|cet)\s*hours/i,
  /daily\s*live\s*calls?\s*required/i,
  /must\s*overlap\s*full\s*business\s*day/i,
  /\b(?:9|8)\s*(?:am|AM)[-–]\s*(?:5|6)\s*(?:pm|PM)\s*(?:EST|PST|CET|ET)\b/
];

const hasSyncReject = SYNC_REJECT.some(p => p.test(text));
if (hasSyncReject) {
  item.json._async_level = 'none';
  item.json._async_rejected = true;
  return [item];
}

let asyncLevel = 'unknown';
if (ASYNC_HIGH.some(p => p.test(text))) asyncLevel = 'high';
else if (ASYNC_MED.some(p => p.test(text))) asyncLevel = 'medium';
else asyncLevel = 'low';

item.json._async_level = asyncLevel;
item.json._async_rejected = false;
return [item];

// Role fit categorizer
const item = $input.first();
const text = `${item.json.job_title} ${item.json.description} ${item.json.tags}`.toLowerCase();

const ROLES = [
  { cat: 'data_analyst', patterns: [/data\s*analyst/i, /analytics\s*analyst/i] },
  { cat: 'data_scientist', patterns: [/data\s*scientist/i, /junior\s*data\s*scientist/i, /ml\s*engineer/i, /machine\s*learning/i] },
  { cat: 'bi_analyst', patterns: [/business\s*intelligence/i, /\bbi\s*analyst/i, /\bpower\s*bi\b/i, /\btableau\b/i] },
  { cat: 'marketing_analyst', patterns: [/marketing\s*analyst/i, /performance\s*marketing/i, /growth\s*analyst/i, /digital\s*marketing\s*analyst/i] },
  { cat: 'ai_marketing', patterns: [/ai\s*marketing/i, /ai-assisted\s*marketing/i, /marketing\s*automation/i, /martech/i] },
  { cat: 'ai_automation', patterns: [/ai\s*automation/i, /workflow\s*automation/i, /n8n/i, /zapier/i, /process\s*automation/i] },
  { cat: 'growth_analyst', patterns: [/growth\s*analyst/i, /growth\s*hacker/i, /user\s*acquisition/i, /\bseo\s*analyst\b/i] },
  { cat: 'ai_workflow', patterns: [/ai\s*workflow/i, /ai\s*consultant/i, /llm/i, /prompt\s*engineer/i] },
  { cat: 'creative_data', patterns: [/creative\s*strategist/i, /creative\s*analyst/i, /content\s*analyst/i] }
];

const ADJACENT = [
  /analyst/i, /data/i, /marketing/i, /growth/i, /automation/i, /reporting/i,
  /dashboard/i, /insights/i, /research/i, /intelligence/i
];

let roleCategory = 'other';
let roleFit = 'none';

for (const role of ROLES) {
  if (role.patterns.some(p => p.test(text))) {
    roleCategory = role.cat;
    roleFit = 'primary';
    break;
  }
}

if (roleFit === 'none' && ADJACENT.some(p => p.test(text))) {
  roleFit = 'adjacent';
  roleCategory = 'adjacent';
}

item.json._role_category = roleCategory;
item.json._role_fit = roleFit;
return [item];

// Score each job 0-100
const item = $input.first();
let score = 0;
const reasons = [];

// Taiwan eligibility (40 pts max)
const tw = item.json.taiwan_eligible;
const hasSignal = item.json._has_keep_signal;
const locRisk = item.json.location_risk;
if (tw === 'yes' || (hasSignal && tw !== 'no')) {
  score += 40;
  reasons.push('Global/worldwide remote eligible (+40)');
} else if (tw === 'unclear' && locRisk !== 'high') {
  score += 20;
  reasons.push('No country restriction detected (+20)');
} else if (locRisk === 'low') {
  score += 30;
  reasons.push('APAC or low location risk (+30)');
}

// Async fit (25 pts max)
const asyncLevel = item.json._async_level;
if (asyncLevel === 'high') { score += 25; reasons.push('Clearly async (+25)'); }
else if (asyncLevel === 'medium') { score += 20; reasons.push('Flexible hours (+20)'); }
else if (asyncLevel === 'low') { score += 10; reasons.push('Remote first signal (+10)'); }

// Role fit (25 pts max)
const roleFit = item.json._role_fit;
if (roleFit === 'primary') { score += 25; reasons.push('Strong role fit (+25)'); }
else if (roleFit === 'adjacent') { score += 15; reasons.push('Adjacent role (+15)'); }

// Salary fit (25 pts max)
const salaryText = (item.json.salary || '').replace(/,/g, '');
const salaryNums = salaryText.match(/\d{4,}/g) || [];
const salaryMax = salaryNums.length > 0 ? Math.max(...salaryNums.map(Number)) : 0;
if (salaryMax >= 5000) { score += 25; reasons.push('Salary ≥ $5k/mo (+25)'); }
else if (salaryMax >= 3000) { score += 15; reasons.push('Salary ≥ $3k/mo (+15)'); }
else if (salaryText.length > 0) { score += 10; reasons.push('Salary listed (+10)'); }

// Generate why_good_fit summary
const why = [
  tw === 'yes' ? 'Taiwan eligible confirmed.' : '',
  asyncLevel === 'high' ? 'Async-friendly work culture.' : asyncLevel === 'medium' ? 'Flexible schedule.' : '',
  roleFit === 'primary' ? `Matches Jerry's core role (${item.json._role_category}).` : roleFit === 'adjacent' ? 'Adjacent to core skills.' : '',
  salaryMax >= 3000 ? `Salary ${salaryText} is competitive.` : ''
].filter(Boolean).join(' ');

item.json.score = score;
item.json._score_reasons = reasons.join('; ');
item.json.why_good_fit = why || 'Needs manual review.';

// Final decision
let decision;
if (item.json.taiwan_eligible === 'no' || item.json.location_risk === 'high' || score < 70) {
  decision = 'reject';
} else if (item.json.taiwan_eligible === 'unclear' && score >= 85) {
  decision = 'manual_check';
} else if (score >= 85 && item.json.taiwan_eligible === 'yes') {
  decision = 'apply';
} else if (score >= 70) {
  decision = 'review';
} else {
  decision = 'reject';
}

item.json.decision = decision;
item.json.application_status = 'new';

return [item];

// Prepare cover letter prompt for high-scoring jobs
const item = $input.first();
item.json._cover_letter_prompt = `Write a short cover letter for Jerry.

Jerry is based in Taiwan and wants async global remote work.

Background:
- Bilingual: English and Mandarin (grew up in California and Taiwan)
- Digital marketing background with data science bootcamp experience
- Skills: Python, SQL, Tableau, Power BI, GA4, Meta Ads, Google Ads
- AI tools: ChatGPT, Claude, Gemini, Cursor
- Experience: dashboards, EDA, machine learning projects, customer segmentation, fraud detection, marketing analytics, SEO, PPC, performance marketing

Job details:
Title: ${item.json.job_title}
Company: ${item.json.company}
Why it fits: ${item.json.why_good_fit}

Make the letter specific to this job. Mention how Jerry can help the company:
- Reduce manual analysis time
- Improve reporting speed
- Connect marketing and data
- Build AI-assisted workflows
- Turn messy data into business action

Keep it under 220 words.
Tone: confident, direct, human, not desperate.`;
return [item];

// Parse cover letter response and attach to job
const aiResponse = $input.first().json;
const jobData = $('Prepare Cover Letter Prompt').first().json;

let coverLetter = '';
try {
  coverLetter = aiResponse.content[0].text || '';
} catch (e) {
  coverLetter = 'Error generating cover letter.';
}

return [{
  json: {
    ...jobData,
    cover_letter_draft: coverLetter
  }
}];

