// Build daily digest email
const allItems = $input.first().json.data || [];

const filtered = allItems
  .filter(j => j.score >= 70)
  .sort((a, b) => (b.score || 0) - (a.score || 0));

const topJobs = filtered.slice(0, 10);
const manualCheck = filtered.filter(j => j.taiwan_eligible === 'unclear' && j.score >= 70);

// Count rejections
const allRaw = allItems;
const rejectedUS = allRaw.filter(j => (j._reject_reason || '').match(/us.only|usa.only|united.states/i)).length;
const rejectedEU = allRaw.filter(j => (j._reject_reason || '').match(/eu.only|europe/i)).length;
const rejectedHybrid = allRaw.filter(j => (j._reject_reason || '').match(/hybrid|onsite/i)).length;
const rejectedTZ = allRaw.filter(j => j.timezone_risk === 'high').length;

let body = `Daily Taiwan Eligible Async Remote Jobs\n`;
body += `Date: ${new Date().toLocaleDateString('en-US', { timeZone: 'Asia/Taipei' })}\n`;
body += `Total fetched today: ${allRaw.length} | Passed filter: ${filtered.length}\n\n`;
body += `${'='.repeat(60)}\nTOP JOBS TODAY\n${'='.repeat(60)}\n\n`;

topJobs.forEach((j, i) => {
  body += `${i + 1}. ${j.job_title}\n`;
  body += `   Company: ${j.company}\n`;
  body += `   Score: ${j.score}/100\n`;
  body += `   Taiwan Eligible: ${j.taiwan_eligible}\n`;
  body += `   Reason: ${j.taiwan_reason}\n`;
  body += `   Async Level: ${j._async_level}\n`;
  body += `   Timezone Risk: ${j.timezone_risk}\n`;
  body += `   Salary: ${j.salary || 'Not listed'}\n`;
  body += `   Why it fits Jerry: ${j.why_good_fit}\n`;
  body += `   Apply: ${j.job_url}\n\n`;
});

if (manualCheck.length > 0) {
  body += `${'='.repeat(60)}\nMANUAL CHECK NEEDED (Taiwan eligibility unclear)\n${'='.repeat(60)}\n\n`;
  manualCheck.slice(0, 5).forEach((j, i) => {
    body += `${i + 1}. ${j.job_title} at ${j.company} (Score: ${j.score}) — ${j.taiwan_reason}\n`;
    body += `   ${j.job_url}\n\n`;
  });
}

body += `${'='.repeat(60)}\nREJECTED SUMMARY\n${'='.repeat(60)}\n`;
body += `Rejected: US only: ${rejectedUS}\n`;
body += `Rejected: EU only: ${rejectedEU}\n`;
body += `Rejected: Hybrid/Onsite: ${rejectedHybrid}\n`;
body += `Rejected: High timezone risk: ${rejectedTZ}\n`;

return [{ json: { digest_body: body, job_count: filtered.length } }];

// Prep low-score jobs for Rejected sheet
const item = $input.first();
return [{
  json: {
    date_rejected: new Date().toISOString().split('T')[0],
    job_title: item.json.job_title,
    company: item.json.company,
    job_url: item.json.job_url,
    reason: `Score ${item.json.score}/100 — ${item.json.taiwan_reason || item.json._score_reasons}`
  }
}];
